/**********************
 *	 GLOBAL FUNCTIONS
 **********************/
void tools_alarm_app_item_ui_event_actions(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    //lv_obj_t * target = lv_event_get_target(e);
    uint32_t        child_cnt = lv_obj_get_child_cnt(ui_FpToolsAlarmItemIndex);
    uint32_t        child_id = get_tools_alarm_item_childId(child_cnt);
    lv_obj_t *      get_focus_obj = NULL;
    lv_obj_t *      pre_focus_obj = NULL;

    //	__inf("tools_alarm_app_item_ui_event_actions 00 =%d\r\n",event_code);
    switch (event_code)
    {
        case LV_EVENT_SCREEN_LOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_add_obj(lv_group_get_default(),obj);
                    lv_group_focus_obj(obj);
                    }

                }
            break;

        case LV_EVENT_SCREEN_UNLOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_remove_obj(obj);
                    }
                }
            break;

        case LV_EVENT_KEY:
            {
                uint32_t        key = lv_event_get_key(e);

                __inf("tools_alarm_app_item_ui_event_actions11 LV_EVENT_KEY:%d\r\n",key);

                if (key == LV_KEY_UP) {
                    //__inf("LV_KEY_UP,child_id:%d,child_cnt:%d\r\n",child_id,child_cnt);
                    if (child_id != 0) {
                        pre_focus_obj       = lv_obj_get_child(ui_FpToolsAlarmItemIndex,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);



                        get_focus_obj       = lv_obj_get_child(ui_FpToolsAlarmItemIndex,child_id - 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(get_focus_obj,PHONEBOOK_NAME_TEXT_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(get_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        if ((child_id - 1) == 0) {
                            lv_obj_scroll_to_y(ui_FpToolsAlarmItemIndex,0,LV_ANIM_OFF);

                            }
                        else {
                            lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);

                            }

                        }
                    else {
                        pre_focus_obj       = lv_obj_get_child(ui_FpToolsAlarmItemIndex,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        get_focus_obj       = lv_obj_get_child(ui_FpToolsAlarmItemIndex,child_cnt - 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(get_focus_obj,PHONEBOOK_NAME_TEXT_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(get_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        //__inf("get_focus_obj :%d\r\n",lv_obj_has_state(get_focus_obj, LV_STATE_FOCUSED));
                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);

                        }

                    {
                        lv_obj_t *      label;
                        uint8_t         str_buf[100];

                        memset(str_buf,0,100);
                        label               = lv_obj_get_child(get_focus_obj,0);
                        strcpy(str_buf,lv_label_get_text(label));
                        strcat(str_buf,";");
                        label               = lv_obj_get_child(get_focus_obj,1);
                        strcat(str_buf,lv_label_get_text(label));
                        app_fp_play_tts_menu((str_buf));
                        }

                    }
                else if (key == LV_KEY_DOWN) {

                    if (child_id != child_cnt - 1) {
                        pre_focus_obj       = lv_obj_get_child(ui_FpToolsAlarmItemIndex,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        get_focus_obj       = lv_obj_get_child(ui_FpToolsAlarmItemIndex,child_id + 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(get_focus_obj,PHONEBOOK_NAME_TEXT_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(get_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);

                        }
                    else {
                        pre_focus_obj       = lv_obj_get_child(ui_FpToolsAlarmItemIndex,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        get_focus_obj       = lv_obj_get_child(ui_FpToolsAlarmItemIndex,0);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(get_focus_obj,PHONEBOOK_NAME_TEXT_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(get_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        lv_obj_scroll_to_y(ui_FpToolsAlarmItemIndex,0,LV_ANIM_OFF);

                        }

                    {
                        lv_obj_t *      label;
                        uint8_t         str_buf[100];

                        memset(str_buf,0,100);
                        label               = lv_obj_get_child(get_focus_obj,0);
                        strcpy(str_buf,lv_label_get_text(label));
                        strcat(str_buf,";");
                        label               = lv_obj_get_child(get_focus_obj,1);
                        strcat(str_buf,lv_label_get_text(label));
                        app_fp_play_tts_menu((str_buf));
                        }
                    }
                else if (key == LV_KEY_LEFT) {

                    }
                else if (key == LV_KEY_DEL) {
                    //uint8_t index = 5;	// 回退到设置的显示设置选项
                    alv_am_win_jump_action(NULL,"tools_alarm",NULL);
                    }
                else if ((key == LV_KEY_ESC) || (key == LV_KEY_ENTER)) {
                    toolsalarm_state_param_t tools_state;
                    s32             ret;

                    ret                 = aic_md_read(MD_ID_TOOLS_ALARM,sizeof(toolsalarm_state_param_t),
                        &tools_state);

                    if (ret) {
                        APP_LOGI("read net cfg error 0x%x\n",ret);
                        }

                    ui_FpToolsSelected  = child_id;

                    if (tools_state.alarm_item[child_id].state) // 闹钟已经打开
                    {
                        //uint8_t index = child_id;
                        alv_am_win_jump_action(NULL,"tool_alarm_set",NULL);
                        }
                    else // 闹钟没有打开，直接去设置闹钟时间
                    {
                        alv_am_win_jump_action(NULL,"tool_alarm_time",NULL);
                        }
                    }
                else if (key == LV_KEY_END)
                    alv_am_app_exit_action_all();

                }
            break;

        default:
            break;
        }


}


