void tools_alarm_app_doing_ui_event_actions(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    //lv_obj_t * target = lv_event_get_target(e);
    if (tools_alarm_doing_timer && (event_code == LV_EVENT_KEY))
        return;

    switch (event_code)
    {
        case LV_EVENT_SCREEN_LOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_add_obj(lv_group_get_default(),obj);
                    lv_group_focus_obj(obj);
                    }

                }
            break;

        case LV_EVENT_SCREEN_UNLOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_remove_obj(obj);
                    }
                }
            break;

        case LV_EVENT_KEY:
            {
                uint32_t        key = lv_event_get_key(e);

                __inf("tools_alarm_app_ui_event_actions 111 LV_EVENT_KEY:%d\r\n",key);

                if (key == LV_KEY_DEL) {
                    //				alv_am_win_jump_action(NULL,"tool_alarm_item",(void *)&index);		
                    if (tools_alarm_doing_one_minute_timer) {
                        lv_timer_del(tools_alarm_doing_one_minute_timer);
                        tools_alarm_doing_one_minute_timer = NULL;
                        }

                    ui_FpToolsSelected  = 1;

                    //active_recent_alarm(1);
                    active_alarm_delay(alarm_doing_number);
                    active_recent_alarm(0);
                    tools_alarm_doing_timer_start();
                    }
                else if ((key == LV_KEY_ESC) || (key == LV_KEY_ENTER)) {
                    s32             ret;
                    toolsalarm_state_param_t alarm_state;

                    if (tools_alarm_doing_one_minute_timer) {
                        lv_timer_del(tools_alarm_doing_one_minute_timer);
                        tools_alarm_doing_one_minute_timer = NULL;
                        }

                    ret                 = aic_md_read(MD_ID_TOOLS_ALARM,sizeof(toolsalarm_state_param_t),
                        &alarm_state);

                    if (ret) {
                        APP_LOGI("read net cfg error 0x%x\n",ret);
                        }

                    if (alarm_state.alarm_item[alarm_doing_number].alarm_type == 0) //单次闹钟
                    {
                        alarm_state.alarm_item[alarm_doing_number].state = 0; //单次闹钟一次后关掉
                        alarm_state.alarm_item[alarm_doing_number].alarm_sign = 0; //
                        ret                 = aic_md_write(MD_ID_TOOLS_ALARM,sizeof(toolsalarm_state_param_t),
                            &alarm_state);

                        if (ret) {
                            APP_LOGI("write net cfg error 0x%x\n",ret);
                            }

                        custom_remove_alarm_by_number(alarm_doing_number);
                        }

                    reset_power_on_alarm_id();

                    //aos_del_alarm_time();
                    if (copy_alarm_para == alarm_doing_number) {
                        copy_alarm_para     = 0xff;
                        aos_memset((u8 *) &copy_alarm_time,0,sizeof(aos_systime));
                        }

                    ui_FpToolsSelected  = 0;
                    active_recent_alarm(0);
                    tools_alarm_doing_timer_start();
                    }
                else if (key == LV_KEY_END) {
                    s32             ret;
                    toolsalarm_state_param_t alarm_state;

                    if (tools_alarm_doing_one_minute_timer) {
                        lv_timer_del(tools_alarm_doing_one_minute_timer);
                        tools_alarm_doing_one_minute_timer = NULL;
                        }

                    ret                 = aic_md_read(MD_ID_TOOLS_ALARM,sizeof(toolsalarm_state_param_t),
                        &alarm_state);

                    if (ret) {
                        APP_LOGI("read net cfg error 0x%x\n",ret);
                        }

                    if (alarm_state.alarm_item[alarm_doing_number].alarm_type == 0) //单次闹钟
                    {
                        alarm_state.alarm_item[alarm_doing_number].state = 0; //单次闹钟一次后关掉
                        alarm_state.alarm_item[alarm_doing_number].alarm_sign = 0; //
                        ret                 = aic_md_write(MD_ID_TOOLS_ALARM,sizeof(toolsalarm_state_param_t),
                            &alarm_state);

                        if (ret) {
                            APP_LOGI("write net cfg error 0x%x\n",ret);
                            }

                        custom_remove_alarm_by_number(alarm_doing_number);
                        }

                    reset_power_on_alarm_id();

                    //aos_del_alarm_time();
                    if (copy_alarm_para == alarm_doing_number) {
                        copy_alarm_para     = 0xff;
                        aos_memset((u8 *) &copy_alarm_time,0,sizeof(aos_systime));
                        }

                    ps_data_msg_send_call_ring_stop();
                    active_recent_alarm(0);
                    alv_am_app_exit_action_all();
                    }

                }
            break;

        default:
            break;
        }


}

static uint32_t app_musicplayer_play_status;

// 日期时间设置
void tools_alarm_doing_win_active(lv_obj_t * win,void * p_param)
{
    extern uint32_t app_musicplayer_get_play_status();
    extern void app_musicplayer_stop();

    if (app_musicplayer_get_play_status())
        app_musicplayer_play_status = 1;

    app_musicplayer_stop();

    app_tts_stop();
    app_recorder_stop();

    if (get_ring_play_status())
        ps_data_msg_send_call_ring_stop();

    settings_fp_flow_set_master_volume(get_alarm_level(),get_alarm_ring(),60 * 1000,NULL); // 最大音量
    backlight_turn_on();
}


void tools_alarm_doing_win_deactive(lv_obj_t * win,void * p_param)
{

    if (false == alv_am_app_is_exist("call")) {
        ps_data_msg_send_call_ring_stop();

        if (app_musicplayer_play_status) {
            app_musicplayer_resume();
            app_musicplayer_play_status = 0;
            }
        }
    else {
        if (app_musicplayer_play_status) {
            set_fp_call_other_app_music_play_status(1);
            app_musicplayer_play_status = 0;
            }

        }

}

void tools_alarm_doing_win_focus(lv_obj_t * win,void * p_param)
{
    ui_FpToolsAlarmDoing_screen_init(p_param);
    lv_disp_load_scr(ui_FpToolsAlarmDoing);

    backlight_turn_on_always();
}


void tools_alarm_doing_win_defocus(lv_obj_t * win,void * p_param)
{
    tools_alarm_doing_one_minute_timer_stop();

    if (ui_FpToolsAlarmDoing)
        lv_obj_del_delayed_custom(ui_FpToolsAlarmDoing,500);

    ui_FpToolsAlarmDoing = NULL;
    backlight_exit_turn_on_always();
}


